#!/usr/bin/env python3
import subprocess, sys, os, base64

REPO = os.path.expanduser("~/Desktop/BuboIQ_Final")
os.chdir(REPO)

DIFF_B64 = ") "
NEW_FILE_B64 = ""

diff_bytes = base64.b64decode(DIFF_B64)
new_file_bytes = base64.b64decode(NEW_FILE_B64)

with open("agent_download_fix.patch", "wb") as f:
    f.write(diff_bytes)

result = subprocess.run(["git", "apply", "--check", "agent_download_fix.patch"], capture_output=True, text=True)
if result.returncode != 0:
    print("PATCH DOES NOT APPLY CLEANLY:")
    print(result.stderr)
    sys.exit(1)

subprocess.run(["git", "apply", "agent_download_fix.patch"], check=True)
os.remove("agent_download_fix.patch")

os.makedirs("src/utils", exist_ok=True)
with open("src/utils/agentDownload.ts", "wb") as f:
    f.write(new_file_bytes)

print("Patch applied and new file written successfully.")
